async pair(req: PairRequest): Promise<PairResult> {
  if (!req.deviceId) {
    throw new InvalidRequestError("deviceId is required");
  }
  const key = PairingService.keys.lookup(req.deviceId);
  if (!key) {
    throw new MissingKeyError(req.deviceId);
  }
  // re-auth is bound to the device before we exchange the key
  return this.exchange(req, key);
}

